  var PAYLOAD_PATTERN = /^(\d{1,32}),([1-9]\d{12})$/;
  var BASE64_PATTERN = /^(?:[A-Za-z0-9+/]{4})*(?:[A-Za-z0-9+/]{2}==|[A-Za-z0-9+/]{3}=)?$/;
